recipes.code:
{
  "inputs": [
    {
      "id": "trustagent-wallet-key",
      "type": "promptString",
      "description": "Private key of a funded Base wallet. Enables the four paid tools, which settle per call in USDC over x402. Omit to run the free tools only — they need no wallet. Requires the optional peer dependency x402-fetch.",
      "password": true
    }
  ],
  "servers": {
    "trustagent": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "trustagent-mcp@0.1.2"
      ],
      "env": {
        "TRUSTAGENT_URL": "https://trust-agent.io",
        "TRUSTAGENT_WALLET_KEY": "${input:trustagent-wallet-key}",
        "TRUSTAGENT_MAX_PER_CALL_USD": "0.05",
        "TRUSTAGENT_MAX_SESSION_USD": "1.00"
      }
    }
  }
}
